    return ''.join(out)

def sentences(s):
    return [x for x in re.split(r'(?<=[.;?])\s+(?=[A-Z`"(*])', s) if x]

def diff(a, b):
    # Whole sentences struck and inserted; a sentence changed in a few words shows the words.
    clean = lambda s: s.replace('**', '').replace('`', '')
    sa, sb = sentences(clean(a)), sentences(clean(b))
    out = []
    for op, i1, i2, j1, j2 in difflib.SequenceMatcher(None, sa, sb, autojunk=False).get_opcodes():
        x, y = sa[i1:i2], sb[j1:j2]
        if op == 'equal': out += [html.escape(s) for s in x]
        elif op == 'replace' and len(x) == len(y) and all(difflib.SequenceMatcher(None, p, q).ratio() > 0.7 for p, q in zip(x, y)):
